package com.campusconnect.dao;

import com.campusconnect.exception.ApiException;
import com.campusconnect.service.ParticipationPolicy;
import com.campusconnect.util.DBConnection;
import java.io.IOException;
import java.sql.*;
import java.util.*;

/** JDBC persistence for student teams, invitations, and event registrations. */
public final class JdbcParticipationDao {
    private static final int TEAM_MAX = ParticipationPolicy.MAX_TEAM_SIZE;
    public List<Map<String,Object>> teams(long user) {
        return query("SELECT t.team_id,t.team_name,t.created_by_user_id owner_user_id,(SELECT COUNT(*) FROM cc_team_members m WHERE m.team_id=t.team_id) member_count FROM cc_teams t WHERE t.created_by_user_id=? OR EXISTS(SELECT 1 FROM cc_team_members m WHERE m.team_id=t.team_id AND m.user_id=?) ORDER BY t.team_id", user,user);
    }
    public Map<String,Object> team(long user,long id) {
        List<Map<String,Object>> rows=query("SELECT t.team_id,t.team_name,t.created_by_user_id owner_user_id,(SELECT COUNT(*) FROM cc_team_members m WHERE m.team_id=t.team_id) member_count FROM cc_teams t WHERE t.team_id=? AND (t.created_by_user_id=? OR EXISTS(SELECT 1 FROM cc_team_members m WHERE m.team_id=t.team_id AND m.user_id=?))",id,user,user);
        if(rows.isEmpty())throw new ApiException(404,"Team not found");
        Map<String,Object> result=rows.get(0);result.put("members",query("SELECT u.user_id,u.display_name FROM cc_team_members m JOIN cc_users u ON u.user_id=m.user_id WHERE m.team_id=? ORDER BY m.joined_at,m.user_id",id));return result;
    }
    public Map<String,Object> createTeam(long user,String name) {
        return transaction(c->{requireStudent(c,user);long id=insertId(c,"INSERT INTO cc_teams(team_name,created_by_user_id) VALUES(?,?)",name,user);try(PreparedStatement s=c.prepareStatement("INSERT INTO cc_team_members(team_id,user_id) VALUES(?,?)")){s.setLong(1,id);s.setLong(2,user);s.executeUpdate();}return teamIn(c,user,id);});
    }
    public Map<String,Object> rename(long user,long id,String name) {
        return transaction(c->{lockTeam(c,id);requireOwner(c,user,id);ensureRosterMutable(c,id);try(PreparedStatement s=c.prepareStatement("UPDATE cc_teams SET team_name=? WHERE team_id=?")){s.setString(1,name);s.setLong(2,id);s.executeUpdate();}return teamIn(c,user,id);});
    }
    public List<Map<String,Object>> invitations(long user) { return query("SELECT i.invitation_id,i.team_id,t.team_name,i.invited_by_user_id owner_user_id,i.invitation_status,i.created_at FROM cc_team_invitations i JOIN cc_teams t ON t.team_id=i.team_id WHERE i.invited_user_id=? AND i.invitation_status='PENDING' ORDER BY i.created_at",user); }
    public Map<String,Object> invite(long owner,long team,long invitee) {
        return transaction(c->{lockTeam(c,team);requireOwner(c,owner,team);ensureRosterMutable(c,team);requireStudent(c,invitee);if(owner==invitee)throw new ApiException(409,"Team owner is already a member");if(isMember(c,team,invitee))throw new ApiException(409,"Student is already a team member");if(scalar(c,"SELECT COUNT(*) FROM cc_team_members WHERE team_id=?",team)>=TEAM_MAX)throw new ApiException(409,"Team has reached its five member limit");long id=insertId(c,"INSERT INTO cc_team_invitations(team_id,invited_user_id,invited_by_user_id) VALUES(?,?,?)",team,invitee,owner);return Map.of("invitationId",id,"teamId",team,"inviteeUserId",invitee,"status","PENDING");});
    }
    public Map<String,Object> respond(long user,long invitation,boolean accept) {
        return transaction(c->{long team;try(PreparedStatement s=c.prepareStatement("SELECT team_id FROM cc_team_invitations WHERE invitation_id=? AND invited_user_id=? AND invitation_status='PENDING'")){s.setLong(1,invitation);s.setLong(2,user);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Invitation not found");team=r.getLong(1);}}
            lockTeam(c,team);try(PreparedStatement s=c.prepareStatement("SELECT invitation_id FROM cc_team_invitations WHERE invitation_id=? AND invited_user_id=? AND invitation_status='PENDING' FOR UPDATE")){s.setLong(1,invitation);s.setLong(2,user);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Invitation not found");}}if(accept){ensureRosterMutable(c,team);requireStudent(c,user);if(isMember(c,team,user))throw new ApiException(409,"Student is already a team member");if(scalar(c,"SELECT COUNT(*) FROM cc_team_members WHERE team_id=?",team)>=TEAM_MAX)throw new ApiException(409,"Team has reached its five member limit");try(PreparedStatement s=c.prepareStatement("INSERT INTO cc_team_members(team_id,user_id) VALUES(?,?)")){s.setLong(1,team);s.setLong(2,user);s.executeUpdate();}}
            try(PreparedStatement s=c.prepareStatement("UPDATE cc_team_invitations SET invitation_status=?,responded_at=SYSTIMESTAMP WHERE invitation_id=? AND invitation_status='PENDING'")){s.setString(1,accept?"ACCEPTED":"DECLINED");s.setLong(2,invitation);if(s.executeUpdate()!=1)throw new ApiException(409,"Invitation is no longer pending");}
            return Map.of("success",true,"invitationId",invitation,"status",accept?"ACCEPTED":"DECLINED");});
    }
    public Map<String,Object> revoke(long owner,long team,long invitation) {
        return transaction(c->{lockTeam(c,team);requireOwner(c,owner,team);try(PreparedStatement s=c.prepareStatement("UPDATE cc_team_invitations SET invitation_status='CANCELLED',responded_at=SYSTIMESTAMP WHERE invitation_id=? AND team_id=? AND invitation_status='PENDING'")){s.setLong(1,invitation);s.setLong(2,team);if(s.executeUpdate()!=1)throw new ApiException(404,"Pending invitation not found");}return Map.of("success",true,"invitationId",invitation,"status","CANCELLED");});
    }
    public Map<String,Object> removeMember(long owner,long team,long member) {
        return transaction(c->{lockTeam(c,team);requireOwner(c,owner,team);if(owner==member)throw new ApiException(409,"The owner cannot leave or be removed; ownership transfer is not supported");ensureRosterMutable(c,team);try(PreparedStatement s=c.prepareStatement("DELETE FROM cc_team_members WHERE team_id=? AND user_id=?")){s.setLong(1,team);s.setLong(2,member);if(s.executeUpdate()!=1)throw new ApiException(404,"Team member not found");}return teamIn(c,owner,team);});
    }
    public Map<String,Object> leave(long user,long team) { return transaction(c->{lockTeam(c,team);long owner=owner(c,team);if(owner==user)throw new ApiException(409,"The owner cannot leave; ownership transfer is not supported");ensureRosterMutable(c,team);try(PreparedStatement s=c.prepareStatement("DELETE FROM cc_team_members WHERE team_id=? AND user_id=?")){s.setLong(1,team);s.setLong(2,user);if(s.executeUpdate()!=1)throw new ApiException(404,"Team membership not found");}return Map.of("success",true,"teamId",team);}); }

    public Map<String,Object> registerIndividual(long user,long event) { return register(user,event,null); }
    public Map<String,Object> registerTeam(long user,long event,long team) { return register(user,event,team); }
    private Map<String,Object> register(long user,long event,Long team) {
        return transaction(c->{requireStudent(c,user);if(team!=null){lockTeam(c,team);requireOwner(c,user,team);}lockEvent(c,event);Event ev=event(c,event);if(!"PUBLISHED".equals(ev.status))throw new ApiException(409,"Event registration is not open");ParticipationPolicy.requireMode(ev.mode,team!=null);if(!eligibleWindow(c,event))throw new ApiException(409,"Event registration is not currently open");
            List<Long> subjects=new ArrayList<>();if(team==null)subjects.add(user);else{int n=0;try(PreparedStatement s=c.prepareStatement("SELECT m.user_id FROM cc_team_members m JOIN cc_users u ON u.user_id=m.user_id WHERE m.team_id=? AND u.role_code='STUDENT' AND u.active_flag='Y' ORDER BY m.user_id")){s.setLong(1,team);try(ResultSet r=s.executeQuery()){while(r.next()){subjects.add(r.getLong(1));n++;}}}ParticipationPolicy.requireTeamSize(n);if(!subjects.contains(user))throw new ApiException(409,"An eligible team must include its owner");}
            for(long member:subjects)if(hasActiveRegistration(c,event,member,team))throw new ApiException(409,"A participant already has an active registration for this event");
            Long existing=findRegistration(c,event,user,team);if(existing!=null)ParticipationPolicy.requireNoPriorRegistration(status(c,existing));int capacity=eventCapacity(c,event);int confirmed=scalar(c,"SELECT COUNT(*) FROM cc_registrations WHERE event_id=? AND registration_status='CONFIRMED'",event);String next=ParticipationPolicy.registrationStatus(capacity==0?null:capacity,confirmed);long id=team==null?insertRegistration(c,event,"INDIVIDUAL",user,null,next):insertRegistration(c,event,"TEAM",null,team,next);
            return registration(c,id,user);});
    }
    public List<Map<String,Object>> myRegistrations(long user,int page,int size) {long offset=(long)(page-1)*size;return query("SELECT r.registration_id,r.event_id,e.event_code,e.event_name,r.registration_type,r.participant_user_id,r.team_id,t.team_name,r.registration_status,r.registered_at FROM cc_registrations r JOIN cc_events e ON e.event_id=r.event_id LEFT JOIN cc_teams t ON t.team_id=r.team_id WHERE r.participant_user_id=? OR EXISTS(SELECT 1 FROM cc_team_members m WHERE m.team_id=r.team_id AND m.user_id=?) ORDER BY r.registered_at DESC,r.registration_id DESC OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",user,user,offset,size);}
    public Map<String,Object> myRegistration(long user,long id) {List<Map<String,Object>> rows=query("SELECT r.registration_id,r.event_id,e.event_code,e.event_name,r.registration_type,r.participant_user_id,r.team_id,t.team_name,r.registration_status,r.registered_at FROM cc_registrations r JOIN cc_events e ON e.event_id=r.event_id LEFT JOIN cc_teams t ON t.team_id=r.team_id WHERE r.registration_id=? AND (r.participant_user_id=? OR EXISTS(SELECT 1 FROM cc_team_members m WHERE m.team_id=r.team_id AND m.user_id=?))",id,user,user);if(rows.isEmpty())throw new ApiException(404,"Registration not found");return rows.get(0);}
    public Map<String,Object> cancel(long user,long id) {return transaction(c->{long event,participant;Long team;try(PreparedStatement s=c.prepareStatement("SELECT event_id,participant_user_id,team_id FROM cc_registrations WHERE registration_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Registration not found");event=r.getLong(1);participant=r.getLong(2);team=nullableLong(r,3);}}if(team!=null)lockTeam(c,team);lockEvent(c,event);String status;try(PreparedStatement s=c.prepareStatement("SELECT registration_status FROM cc_registrations WHERE registration_id=? FOR UPDATE")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Registration not found");status=r.getString(1);}}if(team==null?participant!=user:owner(c,team)!=user)throw new ApiException(404,"Registration not found");if("CANCELLED".equals(status))throw new ApiException(409,"Registration is already cancelled");Event ev=event(c,event);if(!"PUBLISHED".equals(ev.status)||!beforeEventStart(c,event))throw new ApiException(409,"Registration can no longer be cancelled");if(scalar(c,"SELECT COUNT(*) FROM cc_scores WHERE registration_id=?",id)>0)throw new ApiException(409,"A registration with scores cannot be cancelled");try(PreparedStatement s=c.prepareStatement("UPDATE cc_registrations SET registration_status='CANCELLED' WHERE registration_id=?")){s.setLong(1,id);s.executeUpdate();}if("CONFIRMED".equals(status))promoteWaitlist(c,event);return registration(c,id,user);});}
    public List<Map<String,Object>> eventRegistrations(long actor,boolean admin,long event,int page,int size) {return transaction(c->{Event ev=event(c,event);if(!admin){try(PreparedStatement s=c.prepareStatement("SELECT owner_user_id FROM cc_events WHERE event_id=?")){s.setLong(1,event);try(ResultSet r=s.executeQuery()){r.next();if(r.getLong(1)!=actor)throw new ApiException(403,"You may inspect registrations only for your own events");}}}return rows(c,"SELECT r.registration_id,r.event_id,r.registration_type,r.participant_user_id,u.display_name participant_name,r.team_id,t.team_name,r.registration_status,r.registered_at FROM cc_registrations r JOIN cc_events e ON e.event_id=r.event_id LEFT JOIN cc_users u ON u.user_id=r.participant_user_id LEFT JOIN cc_teams t ON t.team_id=r.team_id WHERE r.event_id=? ORDER BY r.registered_at,r.registration_id OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",event,(long)(page-1)*size,size);});}

    private static void promoteWaitlist(Connection c,long event)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT registration_id,participant_user_id,team_id FROM cc_registrations WHERE event_id=? AND registration_status='WAITLISTED' ORDER BY registered_at,registration_id")){s.setLong(1,event);try(ResultSet r=s.executeQuery()){while(r.next()){long id=r.getLong(1);long user=r.getLong(2);Long team=nullableLong(r,3);boolean ok=true;if(team==null)ok=!hasActiveRegistration(c,event,user,null,id);else{try(PreparedStatement m=c.prepareStatement("SELECT COUNT(*) FROM cc_team_members x JOIN cc_users u ON u.user_id=x.user_id WHERE x.team_id=? AND u.role_code='STUDENT' AND u.active_flag='Y'")){m.setLong(1,team);try(ResultSet z=m.executeQuery()){z.next();ok=z.getInt(1)>=2&&z.getInt(1)<=TEAM_MAX;}}if(ok)try(PreparedStatement m=c.prepareStatement("SELECT user_id FROM cc_team_members WHERE team_id=?")){m.setLong(1,team);try(ResultSet z=m.executeQuery()){while(z.next())if(hasActiveRegistration(c,event,z.getLong(1),team,id)){ok=false;break;}}}}if(ok){try(PreparedStatement u=c.prepareStatement("UPDATE cc_registrations SET registration_status='CONFIRMED' WHERE registration_id=?")){u.setLong(1,id);u.executeUpdate();}break;}}}}}
    private static boolean hasActiveRegistration(Connection c,long event,long user,Long ownTeam)throws SQLException {return hasActiveRegistration(c,event,user,ownTeam,null);}
    private static boolean hasActiveRegistration(Connection c,long event,long user,Long ownTeam,Long excludedRegistration)throws SQLException {String sql="SELECT COUNT(*) FROM cc_registrations r WHERE r.event_id=? AND r.registration_status IN ('CONFIRMED','WAITLISTED') AND r.registration_id<>NVL(?, -1) AND (r.participant_user_id=? OR (r.team_id IS NOT NULL AND r.team_id<>NVL(?, -1) AND EXISTS(SELECT 1 FROM cc_team_members m WHERE m.team_id=r.team_id AND m.user_id=?)))";try(PreparedStatement s=c.prepareStatement(sql)){s.setLong(1,event);if(excludedRegistration==null)s.setNull(2,Types.NUMERIC);else s.setLong(2,excludedRegistration);s.setLong(3,user);if(ownTeam==null)s.setNull(4,Types.NUMERIC);else s.setLong(4,ownTeam);s.setLong(5,user);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1)>0;}}}
    private static Long findRegistration(Connection c,long event,long user,Long team)throws SQLException {String sql=team==null?"SELECT registration_id FROM cc_registrations WHERE event_id=? AND participant_user_id=?":"SELECT registration_id FROM cc_registrations WHERE event_id=? AND team_id=?";try(PreparedStatement s=c.prepareStatement(sql)){s.setLong(1,event);s.setLong(2,team==null?user:team);try(ResultSet r=s.executeQuery()){return r.next()?r.getLong(1):null;}}}
    private static String status(Connection c,long id)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT registration_status FROM cc_registrations WHERE registration_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){r.next();return r.getString(1);}}}
    private static long insertRegistration(Connection c,long event,String type,Long user,Long team,String status)throws SQLException {try(PreparedStatement s=c.prepareStatement("INSERT INTO cc_registrations(event_id,registration_type,participant_user_id,team_id,registration_status) VALUES(?,?,?,?,?)",new String[]{"REGISTRATION_ID"})){s.setLong(1,event);s.setString(2,type);if(user==null)s.setNull(3,Types.NUMERIC);else s.setLong(3,user);if(team==null)s.setNull(4,Types.NUMERIC);else s.setLong(4,team);s.setString(5,status);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Missing generated registration ID");return r.getLong(1);}}}
    private static int eventCapacity(Connection c,long id)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT NVL(capacity,0) FROM cc_events WHERE event_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1);}}}
    private static boolean eligibleWindow(Connection c,long id)throws SQLException{return scalar(c,"SELECT COUNT(*) FROM cc_events WHERE event_id=? AND event_status='PUBLISHED' AND registration_opens<=SYSTIMESTAMP AND registration_closes>=SYSTIMESTAMP AND starts_at>SYSTIMESTAMP",id)>0;}
    private static boolean beforeEventStart(Connection c,long id)throws SQLException{return scalar(c,"SELECT COUNT(*) FROM cc_events WHERE event_id=? AND starts_at>SYSTIMESTAMP",id)>0;}
    private static Event event(Connection c,long id)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT event_status,participation_mode FROM cc_events WHERE event_id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Event not found");return new Event(r.getString(1),r.getString(2));}}}
    private record Event(String status,String mode){}
    private static Long nullableLong(ResultSet r,int index)throws SQLException {Object value=r.getObject(index);return value==null?null:((Number)value).longValue();}
    private static long owner(Connection c,long team)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT created_by_user_id FROM cc_teams WHERE team_id=?")){s.setLong(1,team);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Team not found");return r.getLong(1);}}}
    private static void requireOwner(Connection c,long user,long team)throws SQLException {ParticipationPolicy.requireTeamOwner(user,owner(c,team));}
    private static void requireStudent(Connection c,long user)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM cc_users WHERE user_id=? AND role_code='STUDENT' AND active_flag='Y'")){s.setLong(1,user);try(ResultSet r=s.executeQuery()){r.next();if(r.getInt(1)!=1)throw new ApiException(403,"Active student account required");}}}
    private static boolean isMember(Connection c,long team,long user)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM cc_team_members WHERE team_id=? AND user_id=?")){s.setLong(1,team);s.setLong(2,user);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1)>0;}}}
    private static void lockTeam(Connection c,long id)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT team_id FROM cc_teams WHERE team_id=? FOR UPDATE")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Team not found");}}}
    private static void lockEvent(Connection c,long id)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT event_id FROM cc_events WHERE event_id=? FOR UPDATE")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new ApiException(404,"Event not found");}}}
    private static void ensureRosterMutable(Connection c,long id)throws SQLException {if(scalar(c,"SELECT COUNT(*) FROM cc_registrations WHERE team_id=?",id)>0)throw new ApiException(409,"Team roster is locked after its first event registration");}
    private static Map<String,Object> registration(Connection c,long id,long user)throws SQLException {List<Map<String,Object>> rows=rows(c,"SELECT r.registration_id,r.event_id,e.event_code,e.event_name,r.registration_type,r.participant_user_id,r.team_id,t.team_name,r.registration_status,r.registered_at FROM cc_registrations r JOIN cc_events e ON e.event_id=r.event_id LEFT JOIN cc_teams t ON t.team_id=r.team_id WHERE r.registration_id=?",id);if(rows.isEmpty())throw new ApiException(404,"Registration not found");return rows.get(0);}
    private static Map<String,Object> teamIn(Connection c,long user,long id)throws SQLException {List<Map<String,Object>> a=rows(c,"SELECT t.team_id,t.team_name,t.created_by_user_id owner_user_id,(SELECT COUNT(*) FROM cc_team_members m WHERE m.team_id=t.team_id) member_count FROM cc_teams t WHERE t.team_id=?",id);Map<String,Object> result=a.get(0);result.put("members",rows(c,"SELECT u.user_id,u.display_name FROM cc_team_members m JOIN cc_users u ON u.user_id=m.user_id WHERE m.team_id=? ORDER BY m.user_id",id));return result;}
    private interface Work<T>{T run(Connection c)throws Exception;}
    private static <T>T transaction(Work<T> work){try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{T v=work.run(c);c.commit();return v;}catch(Exception e){try{c.rollback();}catch(SQLException x){e.addSuppressed(x);}if(isUnique(e))throw new ApiException(409,"A duplicate team, invitation, or registration already exists");if(e instanceof RuntimeException x)throw x;throw new IllegalStateException("Database operation failed",e);}}catch(IOException|SQLException e){if(isUnique(e))throw new ApiException(409,"A duplicate team, invitation, or registration already exists");throw new IllegalStateException("Database operation failed",e);}}
    private static boolean isUnique(Throwable e){for(Throwable x=e;x!=null;x=x.getCause())if(x instanceof SQLException s&&s.getErrorCode()==1)return true;return false;}
    private static long insertId(Connection c,String sql,Object... args)throws SQLException {try(PreparedStatement s=c.prepareStatement(sql,new String[]{sql.contains("cc_teams")?"TEAM_ID":"INVITATION_ID"})){bind(s,args);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Missing generated identity");return r.getLong(1);}}}
    private static int scalar(Connection c,String sql,Object... args)throws SQLException {try(PreparedStatement s=c.prepareStatement(sql)){bind(s,args);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1);}}}
    private static List<Map<String,Object>> query(String sql,Object... args){try(Connection c=DBConnection.getConnection()){return rows(c,sql,args);}catch(IOException|SQLException e){throw new IllegalStateException("Database query failed",e);}}
    private static List<Map<String,Object>> rows(Connection c,String sql,Object... args)throws SQLException {try(PreparedStatement s=c.prepareStatement(sql)){bind(s,args);try(ResultSet r=s.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object> row=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++){String label=md.getColumnLabel(i).toLowerCase(Locale.ROOT);int jdbcType=md.getColumnType(i);String typeName=md.getColumnTypeName(i).toUpperCase(Locale.ROOT);Object value;if(jdbcType==Types.TIMESTAMP_WITH_TIMEZONE||jdbcType==Types.TIMESTAMP||jdbcType==-100||jdbcType==-101||jdbcType==-102||typeName.contains("TIMESTAMP")){Timestamp ts=r.getTimestamp(i);value=ts==null?null:ts.toInstant().toString();}else value=r.getObject(i);row.put(camel(label),value);}out.add(row);}return out;}}}
    private static String camel(String label){StringBuilder b=new StringBuilder();boolean upper=false;for(char ch:label.toCharArray()){if(ch=='_'){upper=true;continue;}b.append(upper?Character.toUpperCase(ch):ch);upper=false;}return b.toString();}
    private static void bind(PreparedStatement s,Object... args)throws SQLException {for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);}
}
